(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["sr"] = {"ui":{"skip":"Пређи на садржај","back":"← Назад на AI-gile","lang.button":"Језик: {name}","lang.dialog":"Изабери језик","lang.search":"Претражи језике","lang.none":"Ниједан језик не одговара","lang.notYet":"{name} још није преведен","theme.aria":"Пребаци између светле и тамне теме","theme.toLight":"Пређи на светлу тему","theme.toDark":"Пређи на тамну тему","words.underline":"Подвуци ове речи на страници","words.underlineHelp":"Пређи мишем преко истачкане речи или је додирни да видиш шта значи.","index.title":"AI-gile: твој AI тим програмера на једној табли","index.description":"AI-gile је канбан табла за AI тимове који пишу код. Они раде док ти спаваш; ти добијеш једну кратку гомилу ствари да одлучиш, тестираш и прихватиш.","hero.logoAlt":"Икона AI-gile табле","hero.h1.html":"Твој AI тим програмера на једној&nbsp;табли.","hero.alpha":"🐣 Затворена пре-алфа","hero.alphaTitle":"Рано и недовршено: хвала што пробаш!","hero.lede":"Они граде док ти спаваш. Будиш се уз једну кратку гомилу: пар питања, пар ствари за тест, један или два љубичаста дијаманта. Кликни, прихвати, и назад на кафу.","dl.windows":"Windows апликација","dl.browser":"Покрени у прегледачу","dl.soon":"Ускоро","dl.notify":"🔔 Јави ми кад се отвори","dl.notifySmall":"Алфа или бета","hero.secondary":"Agile, али тиму никад не треба кафа за стендап. (Стендап ипак држе.)","pitch.h2":"AI-gile у онолико речи колико хоћеш","pitch.lede":"Изабери дужину, од једне речи до 144. Свака дужина је посебан опис, написан баш за ту величину. Повуци клизач или користи стрелице.","pitch.rangeLabel":"Дужина у речима","pitch.dice":"🎲 друга верзија","pitch.words.one":"{n} реч","pitch.words.other":"{n} речи","pitch.letters.one":"{n} слово","pitch.letters.other":"{n} слова","pitch.chars.one":"{n} знак","pitch.chars.other":"{n} знакова","count.line.html.one":"{n} картица на табли управо сад","count.line.html.other":"{n} картица на табли управо сад","features.aria":"Шта ради","f.pile.h":"Једна гомила за тебе","f.pile.html":"<b>За тебе</b> држи све што чека тебе, преко свих пројеката: питања, ствари за тест, задатке које може само човек. Твој ред каже шта је следеће и колико траје.","f.sleep.h":"Тимови који раде док ти спаваш","f.sleep.p":"Сваки пројекат има вођу и тим AI агената. Коментариши картицу и тим се буди, одради посао и врати је са корацима које може да прати и уморан човек.","f.tester.h":"AI тестер проверава први","f.tester.p":"Пре него што нешто стигне до тебе, тестер прати кораке у копији апликације и показује шта је видео, са снимком екрана. Прелистај оне који су прошли и прихвати једним кликом.","f.proof.h":"Докази, не обећања","f.proof.p":"Свака предаја показује шта се променило: фајлове, разлику, снимке екрана. Не мораш да отвараш сваку апликацију да видиш да ли је готово.","f.chat.h":"Ћаскај са својим вођама","f.chat.p":"Трака као на Discordu: једна икона по пројекту, љубичасти дијаманти за оно што треба тебе. Пошаљи вођи идеју; он је претвори у картице и план, са дугметом ✅ Крени.","f.tidy.h":"Сама се сређује","f.tidy.p":"Сродне картице се спајају у једну, збркани наслови се поправљају, а провера токена држи код сажетим. Мање ствари између којих се пребацујеш, мање мисли.","f.private.h":"Твоје, на твом рачунару","f.private.li1":"Табла ради на твом рачунару и одговара само теби.","f.private.li2":"Приватне поруке међу људима су шифроване од краја до краја.","f.private.li3":"Без налога, без трагача, без колачића.","f.lang.h":"На твом језику","f.lang.p":"Преко 120 језика, од холандског, велшког и јапанског до гусарског, Јоде и клингонског, уз брзи повратак на енглески за програмерске речи.","tl.aria":"Временска линија од првог разговора до плана","tl.h2":"Од првог ћаскања до онога што следи","tl.lede":"Прави датуми и сати, у твојој временској зони. После данас то је план, без обећаних датума.","tl.today":"Данас","tl.planned":"планирано","tl.cards.one":"{n} картица","tl.cards.other":"{n} картица","join.h2":"Придружи се","join.lede":"AI-gile прави један мали човек и много стрпљивих агената. За сада је приватан, у затвореној алфи са пријатељима. Хоћеш да пробаш кад се отвори?","join.btn":"Пријави интересовање","join.small":"Послаћемо ти мејл, ништа друго","footer.tag":"AI-gile. Без трагача, без колачића, без кафе за стендап.","footer.licence":"Пословна лиценца","footer.status":"Статус","footer.privacy":"Шта чувамо","form.sending":"Шаље се…","form.failed":"Није успело: покушај поново касније.","form.offline":"Није могуће допрети до AI-gile: покушај поново касније.","form.keep":"Ово користимо само да ти одговоримо, а затим бришемо. Без трагача, без колачића.","form.keepLink":"Шта чувамо","interest.title":"AI-gile: јави ми кад се алфа отвори","interest.description":"Остави мејл да чујеш кад се отвори затворена алфа или бета AI-gile.","interest.h1":"🔔 Јави ми кад се отвори","interest.lede":"AI-gile је у затвореној пре-алфи. Остави мејл и јавићемо се једном, кад буде места за тебе.","interest.email":"Твој мејл","interest.which":"Који тест?","interest.alpha":"Затворена алфа: рано, грубо, пуно промена","interest.beta":"Бета: стабилнија, касније","interest.both":"Било која, шта прво дође","interest.submit":"Упиши ме на листу","interest.thanks":"Хвала! На листи си.","licence.title":"AI-gile: пословна лиценца","licence.description":"Користиш AI-gile у послу? Затражи бесплатну пословну лиценцу.","licence.h1":"📜 Пословна лиценца","licence.lede":"Користиш AI-gile на послу? Реци нам ко си и чиме се бавиш. Ако то чини нешто добро, лиценца је бесплатна.","licence.company":"Компанија","licence.website":"Веб-сајт","licence.what":"Чиме се бавиш","licence.how":"Како помаже свету","licence.email":"Мејл","licence.submit":"Пријави се","licence.thanks":"Хвала! Одговорићемо мејлом.","status.title":"AI-gile статус","status.h1":"AI-gile статус","status.quiet":"Све мирно","status.intro":"Да ли AI-gile ради управо сада? Ова страница на сваких 5 минута проверава сајт, дељење табли, позиве и преузимање.","status.up":"Ради (одговор за {ms} ms)","status.slow":"Нема одговора на последњу проверу, покушавам поново","status.down":"Не ради: нема одговора на последње две провере","status.svc.web":"Сајт","status.svc.web.offers":"Овај сајт: шта је AI-gile и формулар за интересовање","status.svc.boards":"Дељење табли","status.svc.boards.offers":"Јавне табле, поруке између пријатеља и позивнице","status.svc.calls":"Позиви","status.svc.calls.offers":"Глас, видео и дељење екрана у AI-gile","status.svc.download":"Преузимање","status.svc.download.offers":"Windows инсталер и линкови за позивнице","status.checking":"Проверавам…","status.offline":"Тренутно не могу да допрем до услуге статуса (покушавам поново)","status.updated":"ажурирано {ago}","status.justNow":"управо сад","status.min":"пре {n} мин","status.hours":"пре {n} ч","status.days":"пре {n} д","privacy.title":"AI-gile: шта чувамо","privacy.h1":"Шта чувамо","privacy.lede":"Укратко: само оно што нам пошаљеш, и то не задуго.","privacy.only":"Само оно што нам пошаљеш: оно што упишеш у формулар, на пример свој мејл. Ништа друго о теби.","privacy.sealed":"Запечаћено је тако да га наш сервер не може прочитати: у твом прегледачу пре него што крене (у старијем прегледачу у тренутку кад стигне). Може да га отвори само наша табла.","privacy.server":"Брише се са сервера чим стигне на нашу таблу. Све што је тамо остало и после 30 дана свакако се брише.","privacy.board":"На нашој табли га чувамо само док ти не одговоримо, а онда га и тамо бришемо.","privacy.none":"Без трагача, без колачића, без аналитике.","privacy.local":"Твој језик и избор светле или тамне теме остају у твом прегледачу. Никад нам се не шаљу.","privacy.ask":"Желиш да нестане раније? Одговори на наш мејл и реци нам.","live.h2":"Гледајте како се гради, уживо","live.caption":"Свака картица је скривена: видите облик посла, а не речи.","live.watching.one":"уживо: {n} гледа","live.watching.other":"уживо: {n} гледа","live.last.now":"Последња картица је премештена управо сада","live.last.min.one":"Последња картица је премештена пре {n} минут","live.last.min.other":"Последња картица је премештена пре {n} минута","live.last.hour.one":"Последња картица је премештена пре {n} сат","live.last.hour.other":"Последња картица је премештена пре {n} сати","live.last.day.one":"Последња картица је премештена пре {n} дан","live.last.day.other":"Последња картица је премештена пре {n} дана","live.offline":"Табла уживо мало одмара. Навратите ускоро.","live.cols":"Backlog|Треба урадити|У току|Тим проверава|Чека твој тест|За тим|Готово","pitch.words.few":"{n} речи","pitch.letters.few":"{n} слова","pitch.chars.few":"{n} знака","count.line.html.few":"{n} картице на табли управо сад","tl.cards.few":"{n} картице","live.last.min.few":"Последња картица је премештена пре {n} минута","live.last.hour.few":"Последња картица је премештена пре {n} сата","live.last.day.few":"Последња картица је премештена пре {n} дана"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Канбан.","Роботи.","Делегирано."]},{"n":2,"texts":["Канбан, аутоматизован.","Агенти, организовани.","Идеје, изграђене."]},{"n":3,"texts":["Канбан за роботе.","Идеје постају функције.","Бесплатан канбан агената."]},{"n":5,"texts":["Канбан табла коју воде агенти.","Ти пишеш картице. Агенти граде.","Бесплатно, локално, тестирано, помало смешно."]},{"n":8,"texts":["Бесплатна канбан табла на којој раде AI агенти.","Напиши идеју. Агенти је граде. Ти прихваташ.","Agile за једног човека и много стрпљивих робота."]},{"n":13,"texts":["Канбан табла на твом рачунару на којој AI агенти узимају картице и граде.","Напиши идеју. Тим агената је гради. Тестер је проверава, а ти одлучујеш.","Бесплатно, без налога и трагача: једна табла, пар робота и ти као шеф."]},{"n":21,"texts":["AI-gile је канбан табла за рад са AI агентима који пишу код. Они узимају картице; ти их тестираш и прихваташ.","Сваки пројекат добија вођу и тим AI агената. Коментариши било коју картицу и тим се хвата посла.","Бесплатна, лична табла задатака која ради на твом рачунару. Радници су роботи. Онај који каже да је ти."]},{"n":34,"texts":["Идеје стављаш на таблу. Тим AI агената од њих прави функције које раде, тестира их и враћа ти их са корацима за пробу. Ништа се не рачуна као готово док ти то не кажеш.","AI-gile је кућна канбан табла коју је Рич направио уз пуно помоћи агената којима сада управља. Бесплатна је, ради на твом рачунару и дели се са пријатељима, не продаје се.","Замисли обичну канбан таблу, са колонама од Backlog-а до Готово, само што картице узимају AI агенти. Јављају напредак, питају кад западну и увек сачекају твој палац горе."]},{"n":55,"texts":["AI-gile је канбан табла на којој тим чине AI агенти. Сваки пројекат има вођу који планира посао и помоћнике који граде. Кад је функција спремна, AI тестер је проба и направи снимак екрана, а онда стиже у твоју гомилу. Прихвати је, или коментариши па је раде поново.","Почело је као начин једне особе да прати много AI сесија кодирања одједном, а израсло је у праву таблу. Ради на твом рачунару, не тражи налог и нема трагача. Бесплатна је за пријатеље и радознале. Такође је недовршена, па очекуј грубе ивице и по неко изненађење.","Ево поштене верзије. И даље мораш сам да имаш идеје, и даље мораш сам да провериш резултате. Све између ради AI-gile: држи картице у реду, буди правог агента кад оставиш коментар, показује тачно шта се променило и све то сабира у једну кратку гомилу за тебе, па нема лутања од апликације до апликације."]},{"n":89,"texts":["AI-gile је бесплатна канбан табла коју покрећеш на свом рачунару. Уместо људи, сваки пројекат има тим AI агената: вођу који твоје идеје претвара у картице и план, и помоћнике који узимају картице по приоритету. Кад је нешто направљено, AI тестер прати кораке за тест и показује ти шта је видео. Затим чека у једној гомили која се зове За тебе. Прихватиш га, или коментаришеш и тим покушава поново. Ништа никад не стигне до Готово без тебе.","Неке ствари које можда не очекујеш. Ноћна стража допуњује колону Треба урадити док ти спаваш, бирајући картице којима не треба твој одговор. Бројач токена показује колико су агенти потрошили данас и ове недеље, а No Token Mode им каже да престану да троше. Можеш да пишеш пријатељима, а приватне поруке су шифроване од краја до краја. Табла говори око 120 језика, међу њима холандски, фламански, гусарски и клингонски. Ништа од тога не кошта ни динар, а ни ко ти га не покушава продати.","AI-gile је мали, лични пројекат, а не компанија. Рич је хтео да води неколико AI пројеката кодирања без отварања сваке апликације да провери стање, па су он и агенти направили таблу за то, а онда су помоћу ње направили остатак ње саме. У затвореној је пре-алфи, што значи да ради, углавном, за шачицу пријатеља. Нема странице са ценама, билтена ни плана раста. Ако ти звучи корисно, можеш да затражиш да пробаш кад се мало више отвори."]},{"n":144,"texts":["AI-gile је канбан табла за једног човека и много AI агената. Ради на твом рачунару и потпуно је бесплатна. Додајеш пројекте, и сваки пројекат добија вођу и мали тим. Ћаскаш са вођом, помало као на Discordu, и описујеш идеју; вођа је претвара у картице и план, па чека да притиснеш Крени. Тим пролази кроз картице по приоритету, помоћу једноставног алата за командну линију направљеног за језичке моделе. Пре него што ти се нешто врати, AI тестер прати кораке у копији апликације и прилаже снимак екрана. Готов посао стиже у твоју гомилу са измењеним фајловима и разликом. Прихватиш га, или оставиш коментар па се тим пробуди и покуша поново. Само ти можеш да преместиш картицу у Готово.","Отприлике један дан са AI-gile. Увече оставиш пар коментара: ово дугме је на погрешном месту, она листа треба да буде сортирана, може ли тамни режим. Одеш на спавање. Агенти прочитају коментаре, направе измене, тестирају их и врате ти их. Ако се Треба урадити испразни, ноћна стража га допуни из бекклога картицама којима не треба твој одговор. Ујутру те чека једна кратка гомила: пар питања и неколико ствари за пробу, свака са корацима које може да прати и поспана особа и са снимком екрана како ради. Кликнеш, прихватиш добре и вратиш остале. Бројач токена показује колико је све то потрошило, а No Token Mode је ту за скромније недеље. Затим доручкујеш, а у томе агенти још не могу да помогну.","Прво, шта AI-gile није. Није стартап, није на продају и нико не скупља твоје податке. То је бесплатна табла која ради на твом рачунару, без налога, без трагача и без колачића. А шта јесте: једно уредно место да видиш све своје AI пројекте кодирања одједном, са тимом агената који раде картице и тобом који доносиш одлуке. Спаја сродне картице, поправља збркане наслове и пази колико код остаје сажет. Говори око 120 језика, од холандског и фламанског до гусарског и клингонског. Пријатељи могу да пишу једни другима, приватно и шифровано. Направили су га Рич и велики број стрпљивих агената, углавном користећи њега самог. У затвореној је пре-алфи, па је на местима груб. Ако звучи забавно, лепо питај и можда уђеш раније."]}],"quips":{"1":"Једна реч. Смело. Можда превише смело.","3":"Три речи. Већ поштеније од већине страница производа.","8":"Осам речи. И даље краће од стендапа.","21":"Дужине су, успут, story points. Наравно да јесу.","55":"Педесет пет речи. Две картице су завршене док си ово читао.","144":"То је она дуга. Не постоји 233. Агенти су отишли на спавање."}},"timeline":{"first-idea.name":"Прва идеја","first-idea.line":"Сасвим први разговор, пре него што је постојао иједан ред кода.","first-board.name":"Прва табла","first-board.line":"Табла која прати сопствену изградњу: картице, колоне, превлачење, пројекти.","team-roles.name":"Тим и улоге","team-roles.line":"Профили агената, шаблони тимова, простори и ко шта ради.","install.name":"Инсталација и издања","install.line":"Зип који пријатељ може да инсталира, самоажурирање, канали и повратак на старо.","usage-saver.name":"Штедња потрошње","usage-saver.line":"Мери колико коштају покретања, држи код сажетим, чува твоје ограничење.","friends.name":"Пријатељи и дељење","friends.line":"Приватне поруке, прикривени релеј, позивнице, улоге и дељени пројекти.","languages.name":"Језици","languages.line":"Сваки текст на екрану у језичком фајлу, прво холандски и фламански.","ai-tester.name":"AI тестер","ai-tester.line":"Тестер прво проверава сваку предају и показује шта је видео.","website.name":"Веб-сајт","website.line":"aigile.lol, тизер и ова временска линија.","streaming.name":"Ћаскање и стриминг","streaming.line":"Discord, Twitch, OBS, стример режим, GIF-ови и емоџији.","no-ai.name":"Издање без AI","no-ai.line":"Табла за људе који кодирају без AI, и јавне табле.","night-watch.name":"Ноћна стража","night-watch.line":"Чувар и Scrum Master држе тимове на задатку док ти спаваш.","p-more.name":"Све остало","p-more.line":"Мање идеје које чекају на ред.","p-android.name":"Телефон и Android","p-android.line":"Допри до табле са телефона, а затим изворна Android апликација.","p-release.name":"Алфа и даље","p-release.line":"Затворена алфа, живи сајт, па бета.","p-languages.name":"Још језика","p-languages.line":"Више од сто језика и режим уроњења за оне који уче.","p-engines.name":"Још AI мотора","p-engines.line":"Изабери Claude, Codex или Gemini за сваког агента.","p-pro.name":"Професионална пракса","p-pro.line":"Ознаке ризика, капије за спајање, картице за инциденте и заштитне ограде.","p-self.name":"Брига о теби","p-self.line":"Режим уморног, подсетници за бригу о себи и 4:20.","p-servers.name":"Сервери и раст","p-servers.line":"Глобална подешавања сервера, улоге и планирање раста.","p-livestream.name":"Додаци за стриминг","p-livestream.line":"Twitch ћаскање, прилагођени емоџији и јавни приказ уживо."},"words":{"button":"📖 Речи програмера","h":"📖 Words explained","intro":"The words you meet in AI-gile, in plain language: building it, changing it safely, keeping it running for the people who use it, and working as a team with AI.","search":"Претражи реч…","none":"Ниједна реч се не поклапа.","close":"Затвори","count":{"one":"{count} word","other":"{count} words"},"groups":[{"id":"build","name":"🛠️ Building it"},{"id":"change","name":"🔀 Changing it safely"},{"id":"run","name":"🛎️ Running a service"},{"id":"team","name":"🤝 Working as a team (and with AI)"}],"list":[{"id":"repo","g":"build","word":"Репозиторијум","text":"Фолдер пројекта са кодом и његовом целом историјом комитова, обично чуваном и на GitHub-у.","also":["репозиторијум","репо","репоа","repo","repository"]},{"id":"branch","g":"build","word":"Грана","text":"Посебна линија рада у коду, да се измене могу радити а да се не дира главна верзија.","also":["грана","гране","грани","грану","бранч","branch","branches"]},{"id":"commit","g":"build","word":"Комит","text":"Сачуван снимак кода са кратком белешком шта је промењено. Увек можеш да се вратиш на неки.","also":["комит","комита","комити","комитова","commit","commits"]},{"id":"push","g":"build","word":"Push","text":"Слање сачуваних снимака (комитова) са овог рачунара на GitHub, да буду резервна копија и да се деле."},{"id":"merge","g":"build","word":"Спајање","text":"Враћање измена једне гране у главну верзију."},{"id":"pr","g":"build","word":"Pull request","text":"Захтев да се измене једне гране провере и споје у главну верзију.","also":["PR","pull request"]},{"id":"refactor","g":"build","word":"Рефакторисање","text":"Сређивање кода без промене онога што ради: мањи фајлови, јаснији називи, мање понављања."},{"id":"bug","g":"build","word":"Баг","text":"Нешто што не ради како треба.","also":["баг","бага","багу","багови","багова","bug","bugs"]},{"id":"test","g":"build","word":"Тест","text":"Испробавање готовог посла да се провери да ли ради оно што је тражено, пре него што га прихватиш.","also":["тест","теста","тестови","тестова","тестирање","test","tests"],"noTip":1},{"id":"qa","g":"build","word":"QA","text":"Short for quality assurance: the automatic checks that run before anything goes live. When QA is red, something failed, and it can’t go live until that is fixed.","also":["quality checks"]},{"id":"deploy","g":"change","word":"Деплој","text":"Пуштање нове верзије уживо, на пример на сервер где је људи користе."},{"id":"release","g":"change","word":"Release","text":"A named bundle of finished work that goes live together, with short notes on what changed. 🚀 Releases writes the notes from the done cards.","also":["releases"]},{"id":"rollback","g":"change","word":"Roll back","text":"Going back to the last version that worked when a new one causes trouble. In AI-gile it makes a checklist of the undo steps written on each change.","also":["rollback","roll-back","rolled back"]},{"id":"live","g":"change","word":"Live","text":"The real version that people use, as opposed to a copy for trying things out. Developers also call it production.","also":["production"],"noTip":1},{"id":"change","g":"change","word":"Change","text":"A planned change to something people rely on, written down first: what, why, the risk, when, and how to undo it. Start one with 🔀 Raise a change.","also":["change request","change requests"],"noTip":1},{"id":"risk","g":"change","word":"Risk","text":"Something that could go wrong, scored on how likely and how bad it would be. ⚠️ Risks keeps them in one list, highest score first, each with a date to look again.","also":["risks","risk register"]},{"id":"chgwin","g":"change","word":"Change window","text":"The times when changes may go live, such as a quiet Tuesday evening. Outside a window a change card can’t be finished, unless it is an emergency.","also":["change windows"]},{"id":"gonogo","g":"change","word":"Go / no go","text":"A quick vote just before a change goes live: each person who has to approve says Go or No go. It only goes ahead when they agree.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Approval","text":"Waiting for a yes before work starts. A card a friend raises, or a change, waits in ✅ Approvals until you approve or decline it.","also":["approvals"]},{"id":"quiettime","g":"change","word":"Quiet time","text":"A stretch of time, like a stream, a demo or the night, when nothing goes live. The teams keep working and testing, but going live waits until it ends. Elsewhere it is called a change freeze.","also":["quiet times","change freeze"]},{"id":"service","g":"run","word":"Service","text":"Something you built that people rely on, like a website or an app, looked after so it keeps working. Tick “This project is a service” and say what it offers, who uses it and who is on call.","also":["services"]},{"id":"uptime","g":"run","word":"Uptime check","text":"An automatic check, every few minutes, that your service still answers. If it fails several times in a row, AI-gile opens an incident card by itself.","also":["uptime","uptime checks"]},{"id":"statuspage","g":"run","word":"Status page","text":"A public page that shows whether a service is working (green, orange or red) with the latest update, so the people who use it can check instead of asking.","also":["status pages"]},{"id":"incident","g":"run","word":"Incident","text":"Something that is broken for the people using it right now, like the website being down. A 🔥 incident card jumps the queue: getting it working again comes first.","also":["incidents"]},{"id":"major","g":"run","word":"Major incident","text":"A big incident: many people affected, or money or data at risk. One button puts every team on it (swarm), wakes whoever is on call and asks for a status update every 30 minutes.","also":["major incidents"]},{"id":"oncall","g":"run","word":"On call","text":"Being the one who answers when something breaks, even at night. Each service has an on-call team member who is woken first for its incidents.","also":["on-call"]},{"id":"replyby","g":"run","word":"Reply-by time","text":"How long a card may wait for a first answer, for example an hour for an incident. After that it gets a red clock, so nothing is quietly forgotten. Also called a response target.","also":["reply-by times","response target","response targets"]},{"id":"postmortem","g":"run","word":"Post-mortem","text":"A short look back after an incident: what happened, what helped and what to change, without blaming anyone. An incident can’t be closed without one.","also":["post-mortems","postmortem","post-incident review"]},{"id":"problem","g":"run","word":"Problem","text":"The hidden cause behind one or more incidents. A 🧩 problem card groups incidents that keep coming back, so the cause is found and fixed for good.","also":["problems"],"noTip":1},{"id":"rootcause","g":"run","word":"Root cause","text":"The real reason something broke, not just what you saw going wrong. Fix the root cause and the incident stops coming back.","also":["root causes"]},{"id":"workaround","g":"run","word":"Workaround","text":"A way to keep things working until the real fix is ready, like restarting something when it gets stuck. It is written on the problem card so nobody has to work it out again.","also":["workarounds"]},{"id":"knownerror","g":"run","word":"Known error","text":"A problem whose cause is understood and that has a workaround, but isn’t fixed yet. 🧩 Known errors lists them, so everyone uses the workaround instead of digging again.","also":["known errors"]},{"id":"runbook","g":"run","word":"Runbook","text":"Step-by-step instructions for fixing a known kind of trouble, so it is done the same way, quickly, every time. After a big incident the team can propose one for you to OK.","also":["runbooks"]},{"id":"backup","g":"run","word":"Backup","text":"A saved copy of your data from earlier, to fall back on if something is lost or damaged. AI-gile makes a backup of your boards every day.","also":["backups","back-up","back-ups"]},{"id":"restore","g":"run","word":"Restore","text":"Putting data back from a backup. A backup only really counts once you know it can be restored, so it is worth trying now and then.","also":["restored"]},{"id":"backlog","g":"team","word":"Backlog","text":"Идеје и посао који још нису планирани. Ништа од тога се не ради док се не премести у „Треба урадити“."},{"id":"sprint","g":"team","word":"Спринт","text":"Кратак период рада (често недеља или две) са договореним скупом картица које треба завршити.","also":["спринт","спринта","спринту","спринтом","спринтови","спринтова","sprint","sprints"]},{"id":"standup","g":"team","word":"Стендап","text":"Брза провера: шта је сваки члан тима урадио, шта ради следеће и шта га спречава.","also":["стендап","стендапа","стендапу","стендапови","стендапова","standup","stand-up","stand-ups"]},{"id":"kanban","g":"team","word":"Канбан","text":"Табла са колонама (Треба урадити, У току, Готово) на којој картице иду слева надесно како посао напредује."},{"id":"wip","g":"team","word":"WIP лимит","text":"Work in progress (посао у току): највише картица које колона треба да држи, да тим заврши ствари пре него што започне нове.","also":["WIP","wip лимит","лимит"]},{"id":"dod","g":"team","word":"Definition of Done","text":"The team’s short checklist of what “finished” means, like tested and explained, before a card is handed to you. Its twin, the Definition of Ready, says when a card is clear enough to start.","also":["Definition of Ready"]},{"id":"testpile","g":"team","word":"Test pile","text":"The finished cards waiting for you to try, one after another. Accept one or send it back with a note, and the next one comes up.","also":["test piles"]},{"id":"retro","g":"team","word":"Retro","text":"A look back at how the team works, to agree on one thing to do better. In AI-gile a retro suggests a change to the team’s ways of working, and you say Go or Not yet.","also":["retros","retrospective","retrospectives"]},{"id":"peerreview","g":"team","word":"Peer review","text":"A second pair of eyes: another AI checks each card’s work before it reaches you, so fewer mistakes get through.","also":["code review"]},{"id":"swarm","g":"team","word":"Swarm","text":"All hands on deck: every team drops other work to help on one urgent project until it is sorted. Other projects wait meanwhile.","also":["swarming"]},{"id":"scrummaster","g":"team","word":"Scrum Master","text":"The one who keeps the work flowing: spots stuck cards, nudges the teams and reminds you of what is waiting. In AI-gile the Lead Scrum Master does this across every project.","also":["Lead Scrum Master"]},{"id":"agent","g":"team","word":"Агент","text":"AI који самостално ради на задатку: чита код, прави измене, покреће провере и јавља се.","also":["агент","агента","агенти","агената","agent","agents"]},{"id":"token","g":"team","word":"Токен","text":"Јединица у којој се броји потрошња AI-ја: отприлике неколико слова прочитаног или написаног текста. Мање токена, више остало од плана.","also":["токен","токена","токени","токена","token","tokens"]},{"id":"hook","g":"team","word":"Hook","text":"Мала команда која се сама покреће у одређеном тренутку, нпр. када почне AI сесија, да тим чује твоје коментаре.","also":["hook","hook-ови","hook-а","hooks"]}]}};
